 3	function getPreferredLanguage(acceptLanguage: string | null): string {
 4	  if (!acceptLanguage) {
 5	    return 'unknown';
 6	  }
 7	
 8	  const [firstLanguage] = acceptLanguage.split(',');
 9	  if (!firstLanguage) {
10	    return 'unknown';
11	  }
12	
13	  return firstLanguage.split(';')[0]?.trim() || 'unknown';
14	}
